// Federpendel mit geschwindigkeitsproportionaler Daempfung
// Auslenkung S in m, Zeit in s
Federkraft := -D * S
Reibung := -Daempfung * V
Beschl := (Federkraft + Reibung) / Masse
V := V + Beschl * dt
// S wird mit der neuen Geschwindigkeit berechnet (Euler-Cromer),
// sonst waechst die Amplitude kuenstlich an
S := S + V * dt
Zeit := Zeit + dt
